import json, urllib.request, sys
URL="http://127.0.0.1:8765"
def q(files):
    req=urllib.request.Request(URL+"/ignored",data=json.dumps({"files":files}).encode(),headers={"Content-Type":"application/json"})
    try:
        with urllib.request.urlopen(req,timeout=60) as r: return json.load(r)["ignored"]
    except urllib.error.HTTPError as e: return ("ERR", json.load(e))
def t(ign, paths, sub=None):
    f={p:None for p in paths}; f[".packignore"]=ign
    if sub: f.update(sub)
    return q(f)
