        d=rng.choice(dirlist) or 'a'
        segs=d.split('/')
        segs=segs[rng.randint(0,len(segs)-1):]
        p='/'.join(s if rng.random()<0.6 else rng.choice(['*','**','?','{a,x}','*'+s[-1:],s[:1]+'*','{'+s+',q}']) for s in segs)
        if rng.random()<0.3: p+= '/'+rng.choice(['*','**','a','b','x','?'])
