    if rng.random()<0.05: p=';'+p
    return p
def rlines(rng, dirlist):
    sep=rng.choice(['\n','\n','\r\n','\r'])
    s=sep.join(rpat(rng,dirlist) for _ in range(rng.randint(0,7)))
    if rng.random()<0.5: s+=sep
    return s
def check(tree):
    exp=q(tree)
    try: got=_ignored_entries(list(tree.items()))
    except PackignoreError as e: got=('ERR',)
    if isinstance(exp,tuple): exp=('ERR',)
    return exp,got
if __name__=='__main__':
    seed=int(sys.argv[1]); N=int(sys.argv[2]); bad=0; errs=0
    for i in range(N):
        s=seed*1000000+i
        tree=rtree(random.Random(s))
        exp,got=check(tree)
        if exp==('ERR',): errs+=1
        if got!=exp:
            bad+=1; print('MISMATCH',s, tree, exp, got, flush=True)
            if bad>2: break
    print('done',seed,'bad',bad,'errs',errs)
